61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
72	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
73	     */
74	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
112	        Owner owner = this.clinicService.findOwnerById(ownerId);
113	        if (owner == null) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        List<String> missingFields = new ArrayList<>();
123	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
124	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
125	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
126	        requireNonBlank(missingFields, "address", normalizedAddress);
127	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
128	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
129	        if (!missingFields.isEmpty()) {
130	            throw new MissingRequiredFieldsException(missingFields);
131	        }
132	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
133	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
134	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
135	        requireDailyLimitNotReached(registrationDate);
136	        requireCityBelowCapacity(ownerFieldsDto.getCity());
137	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
138	        requireUniqueTelephone(normalizedTelephone);
139	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
140	        if (!sharesHousehold) {
141	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
142	        }
143	        ownerFieldsDto.setTelephone(normalizedTelephone);
144	        if (ownerFieldsDto.getEmail() != null) {
145	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setAddress(normalizedAddress);
150	        owner.setRegistrationDate(registrationDate);
151	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
152	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
153	        if (sharesHousehold) {
154	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
155	        }
156	        this.clinicService.saveOwner(owner);
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        currentOwner.setAddress(ownerFieldsDto.getAddress());
171	        currentOwner.setCity(ownerFieldsDto.getCity());
172	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
173	        currentOwner.setLastName(ownerFieldsDto.getLastName());
174	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
175	        this.clinicService.saveOwner(currentOwner);
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Transactional
181	    @Override
182	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        this.clinicService.deleteOwner(owner);
188	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Pet pet = petMapper.toPet(petFieldsDto);
200	        owner.setId(ownerId);
201	        pet.setOwner(owner);
202	        pet.getType().setName(null);
203	        this.clinicService.savePet(pet);
204	        PetDto petDto = petMapper.toPetDto(pet);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
206	            .buildAndExpand(pet.getId()).toUri());
207	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner != null) {
215	            Pet currentPet = this.clinicService.findPetById(petId);
216	            if (currentPet != null) {
217	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
218	                currentPet.setName(petFieldsDto.getName());
219	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
220	                this.clinicService.savePet(currentPet);
221	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
230	        HttpHeaders headers = new HttpHeaders();
231	        Visit visit = visitMapper.toVisit(visitFieldsDto);
232	        Pet pet = new Pet();
233	        pet.setId(petId);
234	        visit.setPet(pet);
235	        this.clinicService.saveVisit(visit);
236	        VisitDto visitDto = visitMapper.toVisitDto(visit);
237	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
238	            .buildAndExpand(visit.getId()).toUri());
239	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
240	    }
241	
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner != null) {
248	            Pet pet = owner.getPet(petId);
249	            if (pet != null) {
250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    /**
257	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
258	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
259	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
260	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
261	     *
262	     * @param city the owner's city (already validated non-blank)
263	     * @param lastName the owner's last name (already validated non-blank)
264	     * @return the formatted customer code for the owner being created
265	     */
266	    private String nextCustomerCode(String city, String lastName) {
267	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
268	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
269	        int sequence = (int) this.clinicService.findAllOwners().stream()
270	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
271	            .count() + 1;
272	        return String.format("%s-%s-%04d", city3, last3, sequence);
273	    }
274	
275	    /**
276	     * Counts the existing owners (those already persisted before this create) whose first and last
277	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
278	     * the new owner as its {@code namesakeCount} and echoed back on reads.
279	     *
280	     * @param firstName the incoming owner's first name (already validated non-blank)
281	     * @param lastName the incoming owner's last name (already validated non-blank)
282	     * @return the number of existing namesakes sharing both names case-insensitively
283	     */
284	    private int countNamesakes(String firstName, String lastName) {
285	        return (int) this.clinicService.findAllOwners().stream()
286	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
287	                && lastName.equalsIgnoreCase(existing.getLastName()))
288	            .count();
289	    }
290	
291	    /**
292	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
293	     * whitespace-only), so the caller can reject the request listing every offending field.
294	     */
295	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
296	        if (value == null || value.isBlank()) {
297	            missingFields.add(fieldName);
298	        }
299	    }
300	
301	    /**
302	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
303	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
304	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
305	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
306	     * {@code "+61412345678"}.
307	     *
308	     * @param telephone the raw telephone value from the request
309	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
310	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
311	     */
312	    private static String normalizeTelephone(String telephone) {
313	        String e164 = toE164(telephone);
314	        if (e164 == null) {
315	            throw new InvalidFieldValueException("telephone",
316	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
317	        }
318	        return e164;
319	    }
320	
321	    /**
322	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
323	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
324	     * owners' stored numbers when detecting duplicates.
325	     */
326	    private static String toE164(String telephone) {
327	        if (telephone == null) {
328	            return null;
329	        }
330	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
331	        String digits;
332	        if (cleaned.startsWith("+")) {
333	            digits = cleaned.substring(1);
334	        } else {
335	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
336	            digits = "61" + national;
337	        }
338	        if (!digits.matches("[0-9]{8,15}")) {
339	            return null;
340	        }
341	        return "+" + digits;
342	    }
343	
344	    /**
345	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
346	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
347	     *
348	     * @param email the raw email value from the request (already known to be non-null)
349	     * @return the lower-cased email to be stored and returned
350	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
351	     */
352	    private static String normalizeEmail(String email) {
353	        String trimmed = email.trim();
354	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
355	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
356	        }
357	        return trimmed.toLowerCase(Locale.ROOT);
358	    }
359	
360	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
361	    private static final int MAX_OWNERS_PER_CITY = 50;
362	
363	    /**
364	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
365	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
366	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
367	     *
368	     * @param city the incoming owner's city (already validated non-blank)
369	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
370	     */
371	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
372	    private static final int MAX_OWNERS_PER_DAY = 100;
373	
374	    /**
375	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
376	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
377	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
378	     * date rolled forward to a business day), so this caps the number that may be created per day.
379	     *
380	     * @param businessDay the adjusted business-day registration date of the owner being created
381	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
382	     */
383	    private void requireDailyLimitNotReached(LocalDate businessDay) {
384	        long registeredThatDay = this.clinicService.findAllOwners().stream()
385	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
386	            .count();
387	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
388	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
389	        }
390	    }
391	
392	    /**
393	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
394	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
395	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
396	     * is recorded on the next business day, and every value derived from the registration date uses the
397	     * adjusted date.
398	     *
399	     * @param date the effective registration date (supplied or defaulted), never {@code null}
400	     * @return the same date, or the next Monday when {@code date} is a weekend
401	     */
402	    private static LocalDate toBusinessDay(LocalDate date) {
403	        DayOfWeek day = date.getDayOfWeek();
404	        if (day == DayOfWeek.SATURDAY) {
405	            return date.plusDays(2);
406	        }
407	        if (day == DayOfWeek.SUNDAY) {
408	            return date.plusDays(1);
409	        }
410	        return date;
411	    }
412	
413	    private void requireCityBelowCapacity(String city) {
414	        long cityOwners = this.clinicService.findAllOwners().stream()
415	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
416	            .count();
417	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
418	            throw new CityAtCapacityException(city);
419	        }
420	    }
421	
422	    /**
423	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
424	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
425	     *
426	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
427	     * @throws DuplicateTelephoneException if another owner already uses this telephone
428	     */
429	    private void requireUniqueTelephone(String normalizedTelephone) {
430	        boolean taken = this.clinicService.findAllOwners().stream()
431	            .map(Owner::getTelephone)
432	            .map(OwnerRestControllerV1::toE164)
433	            .filter(existing -> existing != null)
434	            .anyMatch(normalizedTelephone::equals);
435	        if (taken) {
436	            throw new DuplicateTelephoneException(normalizedTelephone);
437	        }
438	    }
439	
440	    /**
441	     * Rejects the request when another owner already shares this household, i.e. has both the same
442	     * last name and the same address once each value is normalized (trimmed, internal whitespace
443	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
444	     * when the request opts in via {@code sharesHousehold}.
445	     *
446	     * @param lastName the incoming owner's last name (already validated non-blank)
447	     * @param address the incoming owner's address (already validated non-blank)
448	     * @throws DuplicateHouseholdException if another owner already has this last name and address
449	     */
450	    private void requireUniqueHousehold(String lastName, String address) {
451	        String normalizedLastName = normalizeForHousehold(lastName);
452	        String normalizedAddress = householdAddressKey(address);
453	        boolean taken = this.clinicService.findAllOwners().stream()
454	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
455	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
456	        if (taken) {
457	            throw new DuplicateHouseholdException(lastName, address);
458	        }
459	    }
460	
461	    /**
462	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
463	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
464	     * comparisons are case-insensitive.
465	     */
466	    private static String normalizeForHousehold(String value) {
467	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
468	    }
469	
470	    /**
471	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
472	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
473	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
474	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
475	     * value normalizes to the empty string, so the required-field check rejects an address that is
476	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
477	     *
478	     * @param address the raw address value from the request (may be {@code null})
479	     * @return the normalized address, or the empty string when blank after normalization
480	     */
481	    private static String normalizeAddress(String address) {
482	        if (address == null) {
483	            return "";
484	        }
485	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
486	        if (collapsed.isEmpty()) {
487	            return "";
488	        }
489	        String[] tokens = collapsed.split(" ");
490	        StringBuilder sb = new StringBuilder();
491	        for (String token : tokens) {
492	            String expanded = switch (token) {
493	                case "ST" -> "STREET";
494	                case "RD" -> "ROAD";
495	                case "AVE" -> "AVENUE";
496	                default -> token;
497	            };
498	            if (sb.length() > 0) {
499	                sb.append(' ');
500	            }
501	            sb.append(expanded);
502	        }
503	        return sb.toString();
504	    }
505	
506	    /**
507	     * Derives the comparison key for an address used by household-duplicate detection and the shared
508	     * household identifier: the address is first put in its canonical normalized form and then
509	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
510	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
511	     */
512	    private static String householdAddressKey(String address) {
513	        return normalizeForHousehold(normalizeAddress(address));
514	    }
515	
516	    /**
517	     * Joins the household identified by this last name and address, returning the stable shared
518	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
519	     * from the normalized last name and address, so every owner in the same household resolves to the
520	     * same value. Any existing household members that predate this feature (or were created without
521	     * opting in) are back-filled with the shared identifier so the whole household agrees.
522	     *
523	     * @param lastName the joining owner's last name (already validated non-blank)
524	     * @param address the joining owner's address (already validated non-blank)
525	     * @return the shared household identifier for this last name and address
526	     */
527	    private String joinHousehold(String lastName, String address) {
528	        String normalizedLastName = normalizeForHousehold(lastName);
529	        String normalizedAddress = householdAddressKey(address);
530	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
531	        this.clinicService.findAllOwners().stream()
532	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
533	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
534	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
535	            .forEach(existing -> {
536	                existing.setHouseholdId(householdId);
537	                this.clinicService.saveOwner(existing);
538	            });
539	        return householdId;
540	    }
541	
542	    /**
543	     * Derives a stable household identifier from the already-normalized last name and address as the
544	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
545	     * always maps to the same identifier.
546	     */
547	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
548	        try {
549	            byte[] digest = MessageDigest.getInstance("SHA-256")
550	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
551	            StringBuilder sb = new StringBuilder();
552	            for (byte b : digest) {
553	                sb.append(String.format("%02X", b));
554	            }
555	            return sb.substring(0, 12);
556	        }
557	        catch (NoSuchAlgorithmException e) {
558	            throw new IllegalStateException("SHA-256 not available", e);
559	        }
560	    }
561	}
